<?php require 'config.php';require 'includes/functions.php';verify();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['hospital']);$city=trim($_POST['city']);$address=trim($_POST['address']);$email=strtolower(trim($_POST['email']));$pw=$_POST['password'];if(!$name||!$city||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)flash('Complete all required fields. Password must be at least 8 characters.','error');else{try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'hospital')");$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO hospitals(user_id,name,address,city) VALUES(?,?,?,?)");$q->execute([$uid,$name,$address,$city]);$pdo->commit();flash('Hospital registered. You can now log in.');go('login.php');}catch(Throwable $e){$pdo->rollBack();flash('Registration failed. Email may already be in use.','error');}}}$title='Hospital registration';require 'includes/header.php';?><div class="formbox"><h1>Register your hospital</h1><form method="post"><?=csrf()?><label>Hospital name<input name="hospital" required></label><label>Contact email<input type="email" name="email" required></label><label>City / location<input name="city" required></label><label>Address<input name="address" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="btn full">Register hospital</button></form></div><?php require 'includes/footer.php';?>